using System.Data;using Microsoft.Data.SqlClient;using TransPort.Api.Configuration;using TransPort.Api.Modules.Gps.DTOs;using TransPort.Api.Modules.Shared.DTOs;using TransPort.Api.Modules.Shared.Repositories;
namespace TransPort.Api.Modules.Gps.Repositories;
public sealed class GpsRepository(ISqlConnectionFactory connections):IGpsRepository
{
 public async Task<GpsResumenDto>ResumenAsync(AlcanceGps a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_gps_leer_resumen");Scope(c,a);await using var r=await c.ExecuteReaderAsync(ct);var ds=new List<GpsDispositivoResumenDto>();while(await r.ReadAsync(ct))ds.Add(new(r.Int32("GpsDispositivoId"),r.Text("IdentificadorExterno"),r.Text("NombreActivo"),NI(r,"TransporteVehiculoId"),r.NullableText("Placa"),NI(r,"MaquinariaEquipoId"),r.NullableText("MaquinariaCodigo"),r.Text("Proveedor"),D(r,"VelocidadMaxima"),r.Bool("EsActivo"),r.NullableDate("UltimaSincronizacion"),r.NullableDate("FechaEvento"),ND(r,"Latitud"),ND(r,"Longitud"),ND(r,"Velocidad"),ND(r,"HorasUso"),ND(r,"Kilometraje"),r.NullableText("Evento"),r.Int32("AlertasAbiertas")));var al=new List<GpsAlertaDto>();if(await r.NextResultAsync(ct))while(await r.ReadAsync(ct))al.Add(new(r.Int64("GpsAlertaId"),r.Int32("GpsDispositivoId"),r.Text("NombreActivo"),r.Text("Tipo"),r.Text("Severidad"),r.Text("Mensaje"),r.Bool("Atendida"),r.Date("Fecha"),r.NullableDate("FechaAtencion"),r.NullableText("AtendidaPor")));return new(ds,al);}
 public async Task<IReadOnlyList<GpsPosicionDto>>RecorridoAsync(int id,DateTime?desde,DateTime?hasta,AlcanceGps a,CancellationToken ct){var x=new List<GpsPosicionDto>();await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_gps_leer_recorrido");c.Parameters.Add("@Id",SqlDbType.Int).Value=id;Scope(c,a);c.Parameters.Add("@FechaDesde",SqlDbType.DateTime2).Value=Db(desde);c.Parameters.Add("@FechaHasta",SqlDbType.DateTime2).Value=Db(hasta);await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))x.Add(new(r.Int64("GpsPosicionId"),r.Int32("GpsDispositivoId"),r.Date("FechaEvento"),D(r,"Latitud"),D(r,"Longitud"),D(r,"Velocidad"),ND(r,"HorasUso"),ND(r,"Kilometraje"),r.NullableText("Evento"),r.Text("OrigenDato"),r.NullableText("DatosFuente"),r.Date("Recibido")));return x;}
 public async Task<GpsOpcionesDto>OpcionesAsync(AlcanceGps a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_gps_leer_opciones");Scope(c,a);await using var r=await c.ExecuteReaderAsync(ct);var v=await Cats(r,ct);var m=await r.NextResultAsync(ct)?await Cats(r,ct):[];return new(v,m);}
 public async Task<int>CrearAsync(CrearGpsDispositivoRequest x,AlcanceGps a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_gps_crear_dispositivo");c.Parameters.Add("@IdentificadorExterno",SqlDbType.NVarChar,100).Value=x.IdentificadorExterno.Trim();c.Parameters.Add("@NombreActivo",SqlDbType.NVarChar,160).Value=x.NombreActivo.Trim();c.Parameters.Add("@VehiculoId",SqlDbType.Int).Value=Db(x.VehiculoId);c.Parameters.Add("@MaquinariaId",SqlDbType.Int).Value=Db(x.MaquinariaId);c.Parameters.Add("@Proveedor",SqlDbType.NVarChar,80).Value=x.Proveedor.Trim();Dec(c,"@VelocidadMaxima",x.VelocidadMaxima,8,2);Scope(c,a);return Convert.ToInt32(await c.ExecuteScalarAsync(ct));}
 public async Task<long>SimularAsync(int id,GpsEventoFuenteDto e,string raw,AlcanceGps a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_gps_simular_evento");c.Parameters.Add("@DispositivoId",SqlDbType.Int).Value=id;c.Parameters.Add("@FechaEvento",SqlDbType.DateTime2).Value=e.FechaEvento??DateTime.UtcNow;Dec(c,"@Latitud",e.Latitud,9,6);Dec(c,"@Longitud",e.Longitud,9,6);Dec(c,"@Velocidad",e.Velocidad,8,2);NDec(c,"@HorasUso",e.HorasUso,18,2);NDec(c,"@Kilometraje",e.Kilometraje,18,2);c.Parameters.Add("@Evento",SqlDbType.NVarChar,80).Value=Db(T(e.Evento));c.Parameters.Add("@DatosFuente",SqlDbType.NVarChar,2000).Value=raw;Scope(c,a);return Convert.ToInt64(await c.ExecuteScalarAsync(ct));}
 public async Task<bool>AtenderAsync(long id,AlcanceGps a,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_gps_atender_alerta");c.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;Scope(c,a);return Convert.ToInt32(await c.ExecuteScalarAsync(ct))>0;}
 public async Task<bool>EliminarAsync(int id,int u,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,"sp_gps_eliminar_dispositivo");c.Parameters.Add("@Id",SqlDbType.Int).Value=id;c.Parameters.Add("@UsuarioId",SqlDbType.Int).Value=u;return Convert.ToInt32(await c.ExecuteScalarAsync(ct))>0;}
 private static async Task<IReadOnlyList<CatalogoDto>>Cats(SqlDataReader r,CancellationToken ct){var x=new List<CatalogoDto>();while(await r.ReadAsync(ct))x.Add(new(r.Int32("Id"),r.Text("Nombre")));return x;}private static void Scope(SqlCommand c,AlcanceGps a){c.Parameters.Add("@UsuarioId",SqlDbType.Int).Value=a.UsuarioId;c.Parameters.Add("@EsAdministrador",SqlDbType.Bit).Value=a.EsAdministrador;}private static SqlCommand P(SqlConnection c,string n)=>new(n,c){CommandType=CommandType.StoredProcedure};private static object Db(object?x)=>x??DBNull.Value;private static string?T(string?x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();private static decimal D(SqlDataReader r,string n)=>r.GetDecimal(r.GetOrdinal(n));private static decimal?ND(SqlDataReader r,string n){var i=r.GetOrdinal(n);return r.IsDBNull(i)?null:r.GetDecimal(i);}private static int?NI(SqlDataReader r,string n){var i=r.GetOrdinal(n);return r.IsDBNull(i)?null:r.GetInt32(i);}private static void Dec(SqlCommand c,string n,decimal v,byte p,byte s){var x=c.Parameters.Add(n,SqlDbType.Decimal);x.Precision=p;x.Scale=s;x.Value=v;}private static void NDec(SqlCommand c,string n,decimal?v,byte p,byte s){var x=c.Parameters.Add(n,SqlDbType.Decimal);x.Precision=p;x.Scale=s;x.Value=Db(v);}
}
